import{_ as t,c as a,o as i,ae as n}from"./chunks/framework.DMK_uHmU.js";const u=JSON.parse('{"title":"Tag Management Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Administration/AI-Management/Settings/tags.md","filePath":"Administration/AI-Management/Settings/tags.md"}'),l={name:"Administration/AI-Management/Settings/tags.md"};function s(o,e,g,r,d,c){return i(),a("div",null,e[0]||(e[0]=[n('<h1 id="tag-management-guide" tabindex="-1">Tag Management Guide <a class="header-anchor" href="#tag-management-guide" aria-label="Permalink to &quot;Tag Management Guide&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#tag-management-guide">Tag Management Guide</a><ul><li><a href="#table-of-contents">Table of Contents</a></li><li><a href="#introduction">Introduction</a></li><li><a href="#accessing-tag-management">Accessing Tag Management</a></li><li><a href="#understanding-tags">Understanding Tags</a></li><li><a href="#tag-management-interface">Tag Management Interface</a></li><li><a href="#managing-tags">Managing Tags</a><ul><li><a href="#adding-tags">Adding Tags</a></li><li><a href="#editing-tags">Editing Tags</a></li><li><a href="#removing-tags">Removing Tags</a></li></ul></li><li><a href="#tag-usage">Tag Usage</a><ul><li><a href="#content-tagging">Content Tagging</a></li><li><a href="#blueprint-tagging">Blueprint Tagging</a></li><li><a href="#knowledge-base-tagging">Knowledge Base Tagging</a></li></ul></li><li><a href="#best-practices">Best Practices</a></li><li><a href="#troubleshooting">Troubleshooting</a></li></ul></li></ul><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The Tag Management system allows administrators to create and manage tags that organize content throughout the platform. Tags provide a flexible categorization system that helps users find and filter content across the AI assistant ecosystem. This guide explains how to effectively use the Tag Management interface to create and maintain tags.</p><h2 id="accessing-tag-management" tabindex="-1">Accessing Tag Management <a class="header-anchor" href="#accessing-tag-management" aria-label="Permalink to &quot;Accessing Tag Management&quot;">​</a></h2><p>The Tag Management component is accessible to users with specific roles:</p><ul><li>Admin</li><li>Content</li><li>Manager</li></ul><p>This interface is typically found in the system settings under AI Settings or Content Management sections.</p><h2 id="understanding-tags" tabindex="-1">Understanding Tags <a class="header-anchor" href="#understanding-tags" aria-label="Permalink to &quot;Understanding Tags&quot;">​</a></h2><p>Tags are lightweight labels that provide additional categorization beyond primary content types:</p><ol><li><p><strong>Purpose</strong>:</p><ul><li>Group related content together</li><li>Create cross-cutting categories</li><li>Improve content discoverability</li><li>Enable more precise filtering</li></ul></li><li><p><strong>Characteristics</strong>:</p><ul><li>Simple text labels</li><li>No hierarchy (flat structure)</li><li>Can be applied to multiple content items</li><li>Can be created centrally or at content creation time</li></ul></li><li><p><strong>Flexibility</strong>:</p><ul><li>System tags (managed centrally)</li><li>Ad-hoc tags (created during content creation)</li><li>Multiple tags can be applied to a single item</li><li>Content can exist without any tags</li></ul></li></ol><h2 id="tag-management-interface" tabindex="-1">Tag Management Interface <a class="header-anchor" href="#tag-management-interface" aria-label="Permalink to &quot;Tag Management Interface&quot;">​</a></h2><p>The Tag Management interface consists of these key components:</p><ol><li><strong>Header</strong>: Title &quot;Manage Tags&quot; with explanatory text</li><li><strong>Tag List</strong>: List of existing system tags</li><li><strong>Add Tag Button</strong>: Button to create new tags</li><li><strong>Tag Input Fields</strong>: Text fields for entering tag names</li></ol><h2 id="managing-tags" tabindex="-1">Managing Tags <a class="header-anchor" href="#managing-tags" aria-label="Permalink to &quot;Managing Tags&quot;">​</a></h2><h3 id="adding-tags" tabindex="-1">Adding Tags <a class="header-anchor" href="#adding-tags" aria-label="Permalink to &quot;Adding Tags&quot;">​</a></h3><p>To create a new system tag:</p><ol><li>Click the &quot;Add Tag&quot; button at the bottom of the tag list</li><li>A new input field will appear</li><li>Enter the desired tag name in the field <ul><li>Keep it concise and descriptive</li><li>Use clear terminology relevant to your organization</li><li>Avoid special characters and overly long names</li></ul></li><li>The tag will be validated as you type</li><li>When you save the settings page, all valid tags will be saved</li></ol><p>Tags added through this interface become available across the system for:</p><ul><li>Content categorization</li><li>Blueprint organization</li><li>Knowledge base classification</li></ul><h3 id="editing-tags" tabindex="-1">Editing Tags <a class="header-anchor" href="#editing-tags" aria-label="Permalink to &quot;Editing Tags&quot;">​</a></h3><p>To modify an existing tag:</p><ol><li>Locate the tag in the list</li><li>Click in its text field</li><li>Edit the tag name as desired</li><li>Changes are applied when the settings page is saved</li></ol><p><strong>Note</strong>: Editing a tag changes it across all content where it&#39;s applied. This is a global change that affects all items using that tag.</p><h3 id="removing-tags" tabindex="-1">Removing Tags <a class="header-anchor" href="#removing-tags" aria-label="Permalink to &quot;Removing Tags&quot;">​</a></h3><p>To delete a tag:</p><ol><li>Locate the tag in the list</li><li>Click the trash icon (×) button on the right side of the tag</li><li>The tag is removed from the list</li><li>When settings are saved, the tag will be removed from the system</li></ol><p><strong>Important</strong>: Removing a tag does not delete content associated with that tag, but those items will no longer have the tag applied. This action cannot be undone.</p><h2 id="tag-usage" tabindex="-1">Tag Usage <a class="header-anchor" href="#tag-usage" aria-label="Permalink to &quot;Tag Usage&quot;">​</a></h2><p>Once created, tags can be used throughout the system in various contexts:</p><h3 id="content-tagging" tabindex="-1">Content Tagging <a class="header-anchor" href="#content-tagging" aria-label="Permalink to &quot;Content Tagging&quot;">​</a></h3><p>In content creation and editing interfaces:</p><ul><li>Select from available system tags</li><li>Create new ad-hoc tags if needed</li><li>Apply multiple tags to a single content item</li><li>Filter content lists by selected tags</li></ul><h3 id="blueprint-tagging" tabindex="-1">Blueprint Tagging <a class="header-anchor" href="#blueprint-tagging" aria-label="Permalink to &quot;Blueprint Tagging&quot;">​</a></h3><p>When configuring AI Blueprints:</p><ul><li>Apply tags to categorize the Blueprint&#39;s purpose</li><li>Use tags to make Blueprints more discoverable</li><li>Filter Blueprint lists using tags</li></ul><h3 id="knowledge-base-tagging" tabindex="-1">Knowledge Base Tagging <a class="header-anchor" href="#knowledge-base-tagging" aria-label="Permalink to &quot;Knowledge Base Tagging&quot;">​</a></h3><p>When managing Knowledge Bases:</p><ul><li>Apply tags to indicate KB subject matter</li><li>Use tags to group related knowledge bases</li><li>Filter KB lists using applied tags</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><p>For effective tag management:</p><ol><li><p><strong>Consistent Naming Conventions</strong>:</p><ul><li>Use clear, descriptive names</li><li>Maintain consistent capitalization (either all lowercase or title case)</li><li>Avoid abbreviations unless widely understood</li><li>Consider using singular nouns (e.g., &quot;Policy&quot; not &quot;Policies&quot;)</li></ul></li><li><p><strong>Tag Organization</strong>:</p><ul><li>Create a core set of standard tags centrally</li><li>Periodically review ad-hoc tags for consolidation</li><li>Combine similar tags to prevent fragmentation</li><li>Remove unused or redundant tags</li></ul></li><li><p><strong>Tagging Strategy</strong>:</p><ul><li>Define tag categories (e.g., department, content type, project)</li><li>Establish guidelines for when to create new tags</li><li>Train users on consistent tag application</li><li>Consider a tag governance process for larger organizations</li></ul></li><li><p><strong>Usage Guidelines</strong>:</p><ul><li>Apply 3-5 relevant tags per item (not too many)</li><li>Focus on the most important characteristics</li><li>Use topics for primary categorization, tags for secondary</li><li>Combine tags with search for best results</li></ul></li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Issue</strong>: Tags not appearing in content creation interfaces</p><ul><li>Refresh the interface to load the latest tags</li><li>Verify that tags were properly saved in the Tag Management interface</li><li>Check user permissions for tag visibility</li></ul><p><strong>Issue</strong>: Unable to add new tags</p><ul><li>Ensure you have the required permissions (Admin, Content, or Manager)</li><li>Check that the tag name is valid and not duplicated</li><li>Verify the tag field is not empty when trying to save</li></ul><p><strong>Issue</strong>: Tag filtering not working properly</p><ul><li>Confirm tags are properly applied to content items</li><li>Try refreshing the interface</li><li>Check if there are any system-wide filtering settings affecting results</li></ul><p><strong>Issue</strong>: Tags disappearing from content</p><ul><li>Verify the tag wasn&#39;t deleted in the Tag Management interface</li><li>Check for any bulk operations that might have modified tags</li><li>Review recent system changes or updates</li></ul><p><strong>Issue</strong>: Too many similar tags creating confusion</p><ul><li>Develop a plan to consolidate similar tags</li><li>Edit tags to standardize naming</li><li>Create organizational guidelines for tag creation</li><li>Periodically audit and clean up the tag list</li></ul><hr><p>For additional assistance with tag management, please contact your system administrator or refer to the platform documentation.</p>',56)]))}const p=t(l,[["render",s]]);export{u as __pageData,p as default};
